import{g as a}from"./words.js";const i="on people's machines",c="Not registered in Straza. A person's own harness runs this server, and a policy rule is the only way to allow its tools.",h="Registered in Straza",E="On people's own machines",d="A server not seen yet",N="Server name",_="The name the server has in the person's MCP settings, for example claude-in-chrome.",m="Not registered in Straza. The person's harness starts this server, and no access row can name it, so a policy rule here is the only way to allow it.",p="A tool of the harness itself, or of an agent built with the kit, that Straza maps to no call type. Claude Code's LSP is one.",A="The exact name the harness gives the tool. Upper and lower case count.",S="The tool's own name, without the server. A * stands for any characters, as in read_*.",u="A harness tool is matched by its whole name, so a pattern matches nothing. Type the name in full, for example LSP.",y="Type the tool's own name, for example navigate, without the mcp__ prefix and the server's name.",R="Add a tool by name",O="Today",w="Harness",T="Asked for and denied",f="No call to this server was denied in the last 24 hours, so there is no tool to tick. Add its tools by name.",I="No harness tool was denied in the last 24 hours. Add the tool by name.",D="Straza cannot list the tools of a server on a person's machine, so this covers tools nobody here has seen. A tool that runs several actions in one call is among them.",v=e=>"denied "+(e===1?"once":e+" times")+", no policy rule covers it",L="a harness tool with no name",C="The harness sent no name, so no policy rule can allow this tool. Update the Straza client or the agent kit on that machine.",H=(e,s)=>"denied "+(e===1?"once":e+" times")+", last "+a(s),n={"claude-code":"Claude Code",codex:"Codex",gemini:"Gemini","python-sdk":"Python kit",console:"Console","self-service":"Self-service page",strazactl:"strazactl","exec-wrapper":"exec wrapper"},M=e=>e.map(s=>n[s]||s).join(", "),g="Denied by default",P="Calls of the last 24 hours that no policy rule covers. A row leaves once a policy rule decides the tool.",W={asked:"Asked for",runs:"Runs in",count:"Denied",last:"Last denied",record:"Newest record"},b="MCP servers on people's own machines",k="Harness tools Straza does not classify",x="Nothing was denied by default in the last 24 hours.",U="Showing the first 200 of more than 200 tools.",z="The calls denied by default",G="Write a policy rule",V=e=>"Write a policy rule for "+e,F="Write a policy rule for this call",Y="Open in Audit",j=e=>"Open record "+e+" in Audit",B=(e,s)=>"Opened from "+(e?"denied calls to "+e:"a denied call to "+s.join(", "))+".",K="A new role",J=e=>"A new application role for the people who may use "+e+".",X="Role name",q="It reaches no registered server. Compose it into a business role, and your identity manager assigns it like any other role.",Q="A role has this name already. Pick it under A role, or type another name.",Z="Name the role.",$="Also creates",ee=e=>"the application role "+e+", in the same draft",se=e=>"This opens "+e+" to every person and agent.",oe="these tools",te=e=>e?"Holders may use "+e+", an MCP server on their own machine, as this role's policy allows.":"Holders may use the harness tools this role's policy allows.",ae=e=>e?e+"-users":"local-tools",r=(e,s)=>e&&e.servers.find(o=>o.server===s)||null,ne=(e,s)=>{if(!e)return[];if(s===null)return e.tools.filter(t=>t.name!=="");const o=r(e,s);return o?o.tools:[]};export{T as A,R as B,S as C,g as D,u as E,y as F,h as G,n as H,oe as I,K as J,J as K,se as L,m as M,L as N,Y as O,D as P,$ as Q,ee as R,z as S,O as T,te as U,ae as V,G as W,B as X,Z as Y,c as Z,i as _,P as a,U as b,x as c,W as d,b as e,k as f,C as g,M as h,A as i,p as j,E as k,H as l,d as m,N as n,j as o,_ as p,F as q,X as r,Q as s,ne as t,q as u,w as v,V as w,I as x,f as y,v as z};
